const seen=new Set(),output=[];
for(const [index,item] of $input.all().entries()){
 const link=String(item.json.link??'').trim(),title=String(item.json.title??'').trim();
 const source_content=[item.json['content:encoded'],item.json.content,item.json.contentSnippet].find(value=>typeof value==='string'&&value.trim())?.trim()||'';
 if(!/^https?:\/\//i.test(link)||!title||!source_content||seen.has(link))continue;
 seen.add(link);output.push({json:{...item.json,link,title,source_content},pairedItem:{item:index}});
}
return output;

const responses=$input.all(),sources=$('Prepare RSS').all();
if(responses.length!==sources.length)throw Error('Quantidade inesperada de respostas da consulta de duplicidade.');
for(const item of responses)if(item.json.success!==true||!Array.isArray(item.json.data))throw Error('A consulta de duplicidade falhou. Nenhuma notícia deste lote será publicada.');
const output=[];
for(let index=0;index<responses.length&&output.length<10;index++){
 if(responses[index].json.data.length===0){
  const source=$('Prepare RSS').itemMatching(index);
  if(!source?.json?.link)throw Error('Vínculo com o RSS não encontrado.');
  output.push({json:source.json,pairedItem:{item:index}});
 }
}
console.log('RSS: '+sources.length+' candidatas; '+output.length+' inéditas selecionadas (máximo 10).');
return output;

const articles = $input.all();
const collection_started_at = $('Schedule Trigger1').first().json.timestamp;
const candidates = articles.flatMap(({json: item}, index) => {
  const url = typeof item.link === 'string' ? item.link.trim() : '';
  const title = typeof item.title === 'string' ? item.title.trim() : '';
  const text = [item.source_content, item['content:encoded'], item.content, item.contentSnippet].find(value => typeof value === 'string' && value.trim());
  if (!(url.startsWith('https://') || url.startsWith('http://')) || !title || !text) return [];
  return [{id:"WKzIlwZIGI3ZHxzo:" + (index + 1),editoria:"sao-paulo",title:title.slice(0,500),url,text:text.trim().slice(0,16000)}];
}).slice(0,10);
return candidates.length ? [{json:{editorial_source:"São Paulo | Agência São Paulo | Diário do Povo",candidates,collection_started_at,publish_by_briefing:true}}] : [];

const items=$input.all(),sources=$('Select Up To 10 New').all(),config=$('Config1').first().json;
if(items.length!==sources.length||items.length>10)throw Error('Quantidade de reescritas diferente das notícias selecionadas.');
const escape=value=>String(value).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
return items.map((item,index)=>{
 const rss=$('Select Up To 10 New').itemMatching(index).json,raw=item.json.output;
 if(!rss?.link)throw Error('Notícia sem vínculo com o item original do RSS.');
 const parsed=typeof raw==='string'?JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'')):raw;
 if(!parsed||Array.isArray(parsed)||typeof parsed!=='object')throw Error('Resposta da IA não é um objeto JSON para '+rss.link);
 for(const field of ['title','hat','content','excerpt','tags'])if(typeof parsed[field]!=='string'||!parsed[field].trim())throw Error('Resposta da IA inválida: '+field+' em '+rss.link);
 let content=parsed.content.replace(/\\[nr]/g,'').replace(/\r?\n/g,'').replace(/<\/?n>/gi,'').replace(/>\s+</g,'><').trim();
 if(!/<p[\s>]/i.test(content)||!content.replace(/<[^>]*>/g,'').trim())throw Error('Conteúdo HTML vazio ou inválido.');
 if(/<(?:script|iframe|object|embed)\b|\bon\w+\s*=/i.test(content))throw Error('Conteúdo HTML contém elementos não permitidos.');
 if(parsed.title.trim().length>500||content.length>1000000)throw Error('Conteúdo excede os limites da API.');
 content=content.replace(/<p>\s*Fonte:[\s\S]*?<\/p>\s*$/i,'')+'<p>Fonte: <a href="'+escape(rss.link)+'" target="_blank" rel="noopener noreferrer">Agência São Paulo</a></p>';
 return {json:{title:parsed.title.trim(),hat:parsed.hat.trim().toUpperCase().slice(0,60),content,excerpt:parsed.excerpt.trim().slice(0,160),tags:parsed.tags.trim(),original_link:rss.link,category_id:Number(config.DEFAULT_CATEGORY_ID),author_id:Number(config.DEFAULT_AUTHOR_ID),status: 'draft'},pairedItem:{item:index}};
});

const output=[];
for(const [index,item] of $input.all().entries()){
 const response=item.json;
 if(response.success!==true||!Array.isArray(response.data))throw Error('Não foi possível confirmar duplicidade antes da publicação.');
 if(response.data.length>0)continue;
 const post=$('Parse AI1').itemMatching(index).json;
 if(!post?.original_link)throw Error('Reescrita sem vínculo com a fonte.');
 output.push({json:post,pairedItem:{item:index}});
}
return output;

const sources = new Map($('Prepare RSS').all().map(({ json: source }) => [source.link, source]));
const result = [];
for (const [index, item] of $input.all().entries()) {
  const response = item.json;
  const draft = $('Confirm Still New').itemMatching(index).json;
  if (response.success === true && response.data?.reused === true) continue;
  if (response.success !== true || !Number.isSafeInteger(response.data?.id) || response.data.status !== 'review' || response.data.reused !== false) {
    throw Error('O CMS não confirmou um novo rascunho para ' + draft.original_link);
  }
  const rss = sources.get(draft.original_link);
  const sourceText = rss && [rss.source_content, rss['content:encoded'], rss.content, rss.contentSnippet].find(value => typeof value === 'string' && value.trim());
  if (!sourceText || (response.data.original_link && response.data.original_link !== draft.original_link)) throw Error('Rascunho sem fonte correspondente: ' + draft.original_link);
  result.push({ json: { post_id: response.data.id, title: draft.title, content: draft.content, original_link: draft.original_link, sources: [{ id: "Agência São Paulo", text: sourceText.trim().slice(0, 16000), url: draft.original_link }] }, pairedItem: { item: index } });
}
return result;
